  const ends=run==='back'?p.cornerSides:p.cornerSides.filter(side=>side===run),stop=ends.length===2||run!=='back'&&ends.length?'Stop the straight rib run at the compound corner opening.':ends.length?`Stop the straight rib run at the ${ends[0]} compound corner opening; at the ${ends[0]==='left'?'right':'left'} wall junction, template and back the future fitted miter between the floor coves, where the vertical wall corner stays sharp.`:`At ${p.corners?`the ${run}`:'each'} wall junction, template and back the future fitted miter between the floor coves; the vertical wall corner stays sharp.`,skinStop=stop.replace('straight rib run','straight cove skin').replace('template and back the future fitted miter','template and fit the supported miter');
